"""Typed source dossier: passage video low byte and caller flags."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0xC2BA,0xC306,'code','Canale superiore: flag di CP 0D consegnati al renderer'),(0xC388,0xC3E4,'code','Glifo: byte basso video e flag del chiamante nel passaggio'),(0xC316,0xC388,'code','Scroll: salvataggi esterni e revoca dei chiamanti non ricostruiti'),(0xD60B,0xD671,'code','Passaggi: contratti indipendenti per L video e F chiamante'),(0xCBC2,0xCC0B,'code','Arrivi propri semplici: conservazione provata fino a 5D25'),(0xC1FD,0xC240,'code','Rifiuti semplici: conservazione dei due operandi del giardiniere')]
notes={0xC2C6:'CP 0D: flag S/Z/H/PV/N/C e bit non documentati X/Y derivati dall’operando. Il confronto originale indipendente copre 256 valori; il renderer confronta tutti i glifi disponibili. n produce10, q26: nessun10 globale.',0xC2EE:'La CALL e JR NZ conservano i flag del CP. Con ingresso C388/SP5D26, PUSH AF scrive F a5D24; il return C2F1 è presente nella traccia naturale.',0xC388:'Writer naturale di5D24: PUSH AF,Holmes0,n di plain,frame5D26,AF6E0A,tick1653/Tue11:32. Giardiniere8 legge10 al3012/Wed10:11, dopo5D1E nella stessa estrazione. 904 scritture su24/25 (452 per byte),nessuna transizione non classificata.',0xC38B:'PUSH HL salva l’indirizzo bitmap prima della ricerca del font. La posizione deriva da x=2+7*colonna,HL=5020+floor(x/8); il byte L è indipendente dalla conoscenza di H.',0xC398:'Ultimo writer naturale di5D1E: risalva HL5032,Holmes0,n di plain,frame5D26,colonna21,tick1653/Tue11:32,returnD65B. Giardiniere8 legge50 al3012/Wed10:11. 974 scritture su1E/1F (487 per byte),nessuna transizione non classificata. Non un50 costante.',0xC31D:'Il prologo dello scroll salva BC/HL/DE sopra il frame della CALL C374. Per i frame profondi può sostituire24 anche quando il glifo interno non lo tocca; revocare i percorsi non proiettati.',0xC374:'La vera CALL lascia il returnC377 e la pulizia ha il proprio stato AF. I contratti dei glifi ordinari non si trasferiscono a tutte le pulizie. Wrap finale e successivi nomi non proiettati revocano i due nuovi campi.',0xD658:'Frame5D26 nel prefisso del passaggio dopo movimento,root e nome grezzo verificato: L video a1E e F chiamante a24. LOOK/frame2A,remote econtainer restano fuori.720 geometrie originali,290 valori noti coincidenti per ciascun campo; L assume19 valori distinti.',0xCBE6:'Nuove1512 ABI originali con marcatori fino25:720 arrivi ordinaryAction propri senza qualificatori attivi preservano1E e24. Nomi composti hanno controesempi. Callerqueued/isolated/relocate restano ignoti; il contratto non introduce25.',0xC21B:'Nuove138 pipeline originali complete;129 rifiuti eleggibili preservano1E e24. Direzioni semplici eEXAMINE assente semplice senza prosa/rootplayer. Non promuovere chiarimenti,ricerche nella prosa o NPC caller.'}
lines=['; Dossier offline: istruzioni e dati tipizzati, verificati e riassemblati sul payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/stack-low-1e';root.mkdir(exist_ok=True);(root/'stack-low-1e.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=170)for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
